import React from 'react';
import { IProfit } from '../../../core/Interface/profitDetailReport.interface';
import { ColumnDef } from '@tanstack/react-table';
import { useTranslation } from 'react-i18next';
import { Box } from '@mui/material';
import { getPriceFormat } from '../../../core/utils';
import { appColors } from '../../../theme/appColors';

const useProfitReportColumns = (
  pageIndex: number,
  pageSize: number,
  currencyCode: string
) => {
  const { t } = useTranslation(['profitReport']);

  return [
    {
      accessorKey: 'sn',
      header: <div style={{ textAlign: 'justify' }}>#</div>,
      size: 50,
      cell: (cell) => {
        const serialNumber = pageIndex * pageSize + cell.row.index + 1;
        return <Box sx={{ textAlign: 'justify' }}>{serialNumber}</Box>;
      },
    },
    {
      accessorKey: 'product.code',
      header: t('profitReport:productCode'),
      size: 180,
    },
    {
      accessorKey: 'product.name',
      header: t('profitReport:productName'),
      size: 200,
    },
    {
      accessorKey: 'qty',
      header: () => (
        <Box sx={{ textAlign: 'center' }}>{t('profitReport:soldQty')}</Box>
      ),
      cell: (cell) => {
        return <Box sx={{ textAlign: 'center' }}>{cell.row.original.qty}</Box>;
      },
      size: 100,
    },
    {
      accessorKey: 'profit',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('profitReport:profit')}</Box>
      ),
      cell: (cell) => {
        return (
          <Box
            sx={{
              textAlign: 'right',
              fontWeight: 'bold',
              color:
                cell.row.original.profit <= 0
                  ? appColors.carmineRed[120]
                  : appColors.darkGreen[40],
            }}
          >
            {' '}
            {getPriceFormat(cell.row.original.profit, currencyCode)}
          </Box>
        );
      },
      size: 200,
    },
  ] as ColumnDef<IProfit>[];
};

export default useProfitReportColumns;
